G("Static GK", "easy", "Which is the longest river of Uttar Pradesh and India's national river?", "उत्तर प्रदेश की सबसे लंबी नदी और भारत की राष्ट्रीय नदी कौन-सी है?", ["Yamuna", "Ganga", "Gomti", "Ghaghara"], ["यमुना", "गंगा", "गोमती", "घाघरा"], "B", "The Ganga is India's national river and flows the longest course in Uttar Pradesh.", "गंगा भारत की राष्ट्रीय नदी है और उत्तर प्रदेश में सबसे लंबा मार्ग तय करती है।");
G("Static GK", "easy", "The Ram Janmabhoomi, a major pilgrimage place of Uttar Pradesh, is in which city?", "उत्तर प्रदेश का प्रमुख तीर्थ स्थल राम जन्मभूमि किस शहर में है?", ["Ayodhya", "Mathura", "Varanasi", "Chitrakoot"], ["अयोध्या", "मथुरा", "वाराणसी", "चित्रकूट"], "A", "The Ram Janmabhoomi is in Ayodhya.", "राम जन्मभूमि अयोध्या में है।");
G("Static GK", "easy", "Which Uttar Pradesh city is known as the birthplace of Lord Krishna?", "उत्तर प्रदेश का कौन-सा शहर भगवान कृष्ण की जन्मभूमि के रूप में जाना जाता है?", ["Mathura", "Vrindavan", "Agra", "Gokul"], ["मथुरा", "वृंदावन", "आगरा", "गोकुल"], "A", "Lord Krishna is believed to have been born in Mathura.", "माना जाता है कि भगवान कृष्ण का जन्म मथुरा में हुआ था।");

// ============================================================ REASONING (37)
R("Number Series", "easy", "Find the missing number: 3, 6, 12, 24, 48, ?", "लुप्त संख्या ज्ञात कीजिए: 3, 6, 12, 24, 48, ?", ["72", "84", "96", "108"], null, "C", "Each term is double the previous one: 48 × 2 = 96.", "प्रत्येक पद पिछले का दोगुना है: 48 × 2 = 96।", () => 48 * 2 === 96);
R("Number Series", "easy", "Find the missing number: 10, 20, 30, 40, ?", "लुप्त संख्या ज्ञात कीजिए: 10, 20, 30, 40, ?", ["45", "50", "55", "60"], null, "B", "The series increases by 10 each time: 40 + 10 = 50.", "श्रृंखला हर बार 10 बढ़ती है: 40 + 10 = 50।", () => 40 + 10 === 50);
R("Number Series", "medium", "Find the missing number: 1, 4, 9, 16, 25, ?", "लुप्त संख्या ज्ञात कीजिए: 1, 4, 9, 16, 25, ?", ["30", "34", "36", "49"], null, "C", "These are the squares of 1, 2, 3, 4, 5; the next is 6² = 36.", "ये 1, 2, 3, 4, 5 के वर्ग हैं; अगला 6² = 36 है।", () => 6 * 6 === 36);
R("Number Series", "medium", "Find the missing number: 2, 5, 11, 23, 47, ?", "लुप्त संख्या ज्ञात कीजिए: 2, 5, 11, 23, 47, ?", ["83", "91", "95", "99"], null, "C", "Each term is double the previous one plus 1: 47 × 2 + 1 = 95.", "प्रत्येक पद पिछले का दोगुना जोड़ 1 है: 47 × 2 + 1 = 95।", () => 2 * 2 + 1 === 5 && 5 * 2 + 1 === 11 && 11 * 2 + 1 === 23 && 23 * 2 + 1 === 47 && 47 * 2 + 1 === 95);
R("Letter Series", "easy", "Find the next letter in the series: B, D, F, H, ?", "श्रृंखला का अगला अक्षर ज्ञात कीजिए: B, D, F, H, ?", ["I", "J", "K", "L"], null, "B", "Every second letter is taken: B, D, F, H, then J.", "एक छोड़कर अक्षर लिए गए हैं: B, D, F, H, फिर J।", () => String.fromCharCode("H".charCodeAt(0) + 2) === "J");
R("Letter Series", "medium", "Find the next group: ZA, YB, XC, WD, ?", "अगला समूह ज्ञात कीजिए: ZA, YB, XC, WD, ?", ["VE", "VF", "UE", "VD"], null, "A", "The first letter moves backward (Z, Y, X, W, V) and the second forward (A, B, C, D, E): VE.", "पहला अक्षर पीछे (Z, Y, X, W, V) और दूसरा आगे (A, B, C, D, E) जाता है: VE।");
R("Coding-Decoding", "easy", "If BOOK is coded as CPPL, how is PAGE coded?", "यदि BOOK को CPPL लिखा जाता है, तो PAGE को कैसे लिखा जाएगा?", ["QBHF", "QAHF", "PBHF", "QBGF"], null, "A", "Each letter is moved one place forward: P→Q, A→B, G→H, E→F, giving QBHF.", "प्रत्येक अक्षर एक स्थान आगे है: P→Q, A→B, G→H, E→F, यानी QBHF।", () => [..."BOOK"].map((c) => String.fromCharCode(c.charCodeAt(0) + 1)).join("") === "CPPL" && [..."PAGE"].map((c) => String.fromCharCode(c.charCodeAt(0) + 1)).join("") === "QBHF");
R("Coding-Decoding", "medium", "If in a code POLICE is written as RQNKEG, how is ARMY written?", "यदि किसी कूट में POLICE को RQNKEG लिखा जाता है, तो ARMY को कैसे लिखा जाएगा?", ["CTOA", "CSOA", "CTNA", "CTOB"], null, "A", "Each letter is moved 2 places forward: P→R, O→Q, L→N, I→K, C→E, E→G. So A→C, R→T, M→O, Y→A, giving CTOA.", "प्रत्येक अक्षर 2 स्थान आगे है: P→R, O→Q, L→N, I→K, C→E, E→G। इसलिए A→C, R→T, M→O, Y→A, यानी CTOA।");
R("Coding-Decoding", "medium", "If PEN is coded as 35 (the sum of the positions of its letters), what is the code for MAP?", "यदि PEN को 35 लिखा जाता है (अक्षरों के स्थानों का योग), तो MAP का कूट क्या होगा?", ["28", "30", "32", "34"], null, "B", "M = 13, A = 1, P = 16, so the sum is 13 + 1 + 16 = 30. (Check: P + E + N = 16 + 5 + 14 = 35.)", "M = 13, A = 1, P = 16, इसलिए योग 13 + 1 + 16 = 30। (जाँच: P + E + N = 16 + 5 + 14 = 35।)", () => { const s = (w) => [...w].reduce((a, c) => a + c.charCodeAt(0) - 64, 0); return s("PEN") === 35 && s("MAP") === 30; });
R("Coding-Decoding", "medium", "In a certain code, '+' means '−', '−' means '×', '×' means '÷' and '÷' means '+'. What is the value of 20 × 4 + 3 − 2 ÷ 1?", "एक कूट में '+' का अर्थ '−', '−' का अर्थ '×', '×' का अर्थ '÷' और '÷' का अर्थ '+' है। 20 × 4 + 3 − 2 ÷ 1 का मान क्या है?", ["0", "1", "2", "3"], null, "A", "Replace the signs: 20 ÷ 4 − 3 × 2 + 1. Now 20 ÷ 4 = 5 and 3 × 2 = 6, so 5 − 6 + 1 = 0.", "चिह्न बदलने पर: 20 ÷ 4 − 3 × 2 + 1 = 5 − 6 + 1 = 0।", () => 20 / 4 - 3 * 2 + 1 === 0);
R("Analogy", "easy", "Fish : Water :: Bird : ?", "मछली : पानी :: पक्षी : ?", ["Nest", "Air", "Tree", "Sky"], ["घोंसला", "हवा", "पेड़", "आसमान"], "B", "A fish lives and moves in water; a bird flies in the air.", "मछली पानी में रहती और चलती है; पक्षी हवा में उड़ता है।");
R("Analogy", "easy", "Light : Bulb :: Sound : ?", "प्रकाश : बल्ब :: ध्वनि : ?", ["Speaker", "Wire", "Battery", "Switch"], ["स्पीकर", "तार", "बैटरी", "स्विच"], "A", "A bulb gives light; a speaker gives sound.", "बल्ब प्रकाश देता है; स्पीकर ध्वनि देता है।");
R("Analogy", "medium", "4 : 64 :: 5 : ?", "4 : 64 :: 5 : ?", ["100", "125", "150", "225"], null, "B", "64 = 4³, so the second number is the cube of the first: 5³ = 125.", "64 = 4³, अर्थात दूसरी संख्या पहली का घन है: 5³ = 125।", () => 4 ** 3 === 64 && 5 ** 3 === 125);
R("Analogy", "medium", "Constable : Police :: Soldier : ?", "सिपाही (कॉन्स्टेबल) : पुलिस :: सैनिक : ?", ["Army", "Court", "School", "Hospital"], ["सेना", "न्यायालय", "विद्यालय", "अस्पताल"], "A", "A constable belongs to the police force; a soldier belongs to the army.", "कॉन्स्टेबल पुलिस बल का सदस्य होता है; सैनिक सेना का सदस्य होता है।");
R("Odd One Out", "easy", "Select the odd one out.", "विषम का चयन कीजिए।", ["Pistol", "Rifle", "Revolver", "Baton"], ["पिस्तौल", "राइफल", "रिवॉल्वर", "डंडा"], "D", "Pistol, rifle and revolver are firearms; a baton is not.", "पिस्तौल, राइफल और रिवॉल्वर आग्नेयास्त्र हैं; डंडा नहीं है।");
R("Odd One Out", "easy", "Select the odd one out among the cities.", "शहरों में से विषम का चयन कीजिए।", ["Lucknow", "Kanpur", "Patna", "Agra"], ["लखनऊ", "कानपुर", "पटना", "आगरा"], "C", "Lucknow, Kanpur and Agra are in Uttar Pradesh; Patna is in Bihar.", "लखनऊ, कानपुर और आगरा उत्तर प्रदेश में हैं; पटना बिहार में है।");
R("Odd One Out", "medium", "Select the odd number: 121, 144, 169, 200", "विषम संख्या चुनिए: 121, 144, 169, 200", ["121", "144", "169", "200"], null, "D", "121 = 11², 144 = 12² and 169 = 13² are perfect squares; 200 is not.", "121 = 11², 144 = 12² और 169 = 13² पूर्ण वर्ग हैं; 200 नहीं है।", () => [121, 144, 169].every((n) => Number.isInteger(Math.sqrt(n))) && !Number.isInteger(Math.sqrt(200)));
R("Odd One Out", "easy", "Select the odd one out among the numbers.", "संख्याओं में से विषम का चयन कीजिए।", ["2", "4", "6", "9"], null, "D", "2, 4 and 6 are even numbers; 9 is odd.", "2, 4 और 6 सम संख्याएँ हैं; 9 विषम है।", () => [2, 4, 6].every((n) => n % 2 === 0) && 9 % 2 === 1);
R("Direction Sense", "medium", "A constable walks 9 km north and then 12 km east. How far is he from his starting point?", "एक सिपाही 9 किमी उत्तर और फिर 12 किमी पूर्व की ओर चलता है। वह अपने प्रारंभिक बिंदु से कितनी दूर है?", ["13 km", "15 km", "17 km", "21 km"], ["13 किमी", "15 किमी", "17 किमी", "21 किमी"], "B", "Distance = √(9² + 12²) = √225 = 15 km.", "दूरी = √(9² + 12²) = √225 = 15 किमी।", () => Math.hypot(9, 12) === 15);
R("Direction Sense", "easy", "Facing north, Ajay turns right and then turns right again. Which direction is he facing now?", "उत्तर की ओर मुँह करके खड़ा अजय दाएँ मुड़ता है और फिर दोबारा दाएँ मुड़ता है। अब उसका मुँह किस दिशा में है?", ["North", "South", "East", "West"], ["उत्तर", "दक्षिण", "पूर्व", "पश्चिम"], "B", "North → right turn: East → right turn: South.", "उत्तर → दाएँ: पूर्व → दाएँ: दक्षिण।");
R("Direction Sense", "medium", "Rahul walks 5 m south, turns left and walks 5 m, then turns left again and walks 5 m. In which direction is he from the starting point?", "राहुल 5 मी दक्षिण चलता है, बाएँ मुड़कर 5 मी चलता है, फिर दोबारा बाएँ मुड़कर 5 मी चलता है। वह प्रारंभिक बिंदु से किस दिशा में है?", ["East", "West", "North", "South"], ["पूर्व", "पश्चिम", "उत्तर", "दक्षिण"], "A", "South 5 m; facing south a left turn is east, so 5 m east; then a left turn faces north, 5 m north. He is back on the start's line, 5 m east of it.", "5 मी दक्षिण; दक्षिण की ओर मुँह हो तो बायाँ पूर्व होता है, इसलिए 5 मी पूर्व; फिर बाएँ मुड़ने पर उत्तर, 5 मी उत्तर। वह प्रारंभिक बिंदु की सीध में उससे 5 मी पूर्व में है।");
R("Blood Relations", "easy", "What is the relation of your father's sister to you?", "आपके पिता की बहन आपकी क्या लगती हैं?", ["Aunt (Bua)", "Aunt (Mausi)", "Mother", "Sister"], ["बुआ", "मौसी", "माँ", "बहन"], "A", "Father's sister is your paternal aunt, called bua.", "पिता की बहन आपकी बुआ होती हैं।");
R("Blood Relations", "medium", "A is B's brother. B is C's mother. C is D's father. How is A related to D?", "A, B का भाई है। B, C की माँ है। C, D का पिता है। A का D से क्या संबंध है?", ["Uncle", "Grand-uncle", "Father", "Brother"], ["चाचा", "दादी का भाई (ग्रैंड-अंकल)", "पिता", "भाई"], "B", "B is C's mother, so B is D's grandmother. A is B's brother, so A is D's grand-uncle (grandmother's brother).", "B, C की माँ है, इसलिए B, D की दादी है। A, B का भाई है, अतः A, D की दादी का भाई (ग्रैंड-अंकल) है।");
R("Blood Relations", "easy", "Pointing to a boy, Sita said, \"He is the son of my mother's only daughter.\" How is the boy related to Sita?", "एक लड़के की ओर संकेत करके सीता ने कहा, \"वह मेरी माँ की इकलौती पुत्री का पुत्र है।\" वह लड़का सीता का क्या लगता है?", ["Brother", "Nephew", "Son", "Cousin"], ["भाई", "भतीजा/भांजा", "पुत्र", "चचेरा भाई"], "C", "Sita's mother's only daughter is Sita herself, so the boy is her son.", "सीता की माँ की इकलौती पुत्री स्वयं सीता है, इसलिए वह लड़का उसका पुत्र है।");
R("Ranking", "easy", "In a queue of 25 persons, Mohan is 10th from the front. What is his position from the back?", "25 व्यक्तियों की कतार में मोहन आगे से 10वें स्थान पर है। पीछे से उसका स्थान क्या है?", ["14th", "15th", "16th", "17th"], ["14वाँ", "15वाँ", "16वाँ", "17वाँ"], "C", "Position from the back = 25 − 10 + 1 = 16.", "पीछे से स्थान = 25 − 10 + 1 = 16।", () => 25 - 10 + 1 === 16);
R("Ranking", "medium", "Raju ranks 14th from the top and 27th from the bottom in a class. How many students are in the class?", "एक कक्षा में राजू ऊपर से 14वें और नीचे से 27वें स्थान पर है। कक्षा में कितने विद्यार्थी हैं?", ["39", "40", "41", "42"], null, "B", "Total = 14 + 27 − 1 = 40.", "कुल = 14 + 27 − 1 = 40।", () => 14 + 27 - 1 === 40);
R("Calendar", "medium", "If 1 January 2026 is a Thursday, what day is 1 February 2026?", "यदि 1 जनवरी 2026 को गुरुवार है, तो 1 फ़रवरी 2026 को कौन-सा दिन होगा?", ["Saturday", "Sunday", "Monday", "Tuesday"], ["शनिवार", "रविवार", "सोमवार", "मंगलवार"], "B", "January has 31 days = 4 weeks + 3 days, so the day moves 3 ahead: Thursday + 3 = Sunday.", "जनवरी में 31 दिन = 4 सप्ताह + 3 दिन, इसलिए दिन 3 आगे खिसकता है: गुरुवार + 3 = रविवार।", () => new Date(Date.UTC(2026, 0, 1)).getUTCDay() === 4 && new Date(Date.UTC(2026, 1, 1)).getUTCDay() === 0);
R("Clock", "easy", "What is the angle between the two hands of a clock at 9:00?", "9:00 बजे घड़ी की दोनों सुइयों के बीच कितना कोण होता है?", ["60°", "90°", "120°", "180°"], null, "B", "At 9:00 the minute hand is at 12 and the hour hand at 9, which is 3 hour-marks = 3 × 30° = 90° apart.", "9:00 बजे मिनट की सुई 12 पर और घंटे की सुई 9 पर होती है, जो 3 खानों यानी 3 × 30° = 90° की दूरी पर हैं।", () => 3 * 30 === 90);
R("Clock", "medium", "A clock shows 4:20 in the mirror image. What is the actual time?", "दर्पण में घड़ी 4:20 दिखाती है। वास्तविक समय क्या है?", ["7:40", "8:40", "7:20", "8:20"], null, "A", "Actual time = 12:00 − 4:20 = 7:40 (subtract the mirror time from 12:00).", "वास्तविक समय = 12:00 − 4:20 = 7:40 (दर्पण का समय 12:00 से घटाएँ)।", () => (12 * 60 - (4 * 60 + 20)) === 7 * 60 + 40);
R("Syllogism", "medium", "Statements: All doctors are educated. Some educated people are honest.\nConclusions: I. Some doctors are honest. II. Some honest people are educated.", "कथन: सभी डॉक्टर शिक्षित हैं। कुछ शिक्षित लोग ईमानदार हैं।\nनिष्कर्ष: I. कुछ डॉक्टर ईमानदार हैं। II. कुछ ईमानदार लोग शिक्षित हैं।", SYL, SYL_HI, "B", "'Some educated people are honest' gives 'some honest people are educated' (II). The honest educated people need not be doctors, so I does not follow.", "'कुछ शिक्षित लोग ईमानदार हैं' से 'कुछ ईमानदार लोग शिक्षित हैं' (II) बनता है। वे ईमानदार शिक्षित लोग डॉक्टर हों, यह ज़रूरी नहीं, इसलिए I सही नहीं है।");
R("Syllogism", "medium", "Statements: All roads are paths. No path is a river.\nConclusions: I. No road is a river. II. Some rivers are roads.", "कथन: सभी सड़कें रास्ते हैं। कोई रास्ता नदी नहीं है।\nनिष्कर्ष: I. कोई सड़क नदी नहीं है। II. कुछ नदियाँ सड़कें हैं।", SYL, SYL_HI, "A", "Roads ⊂ paths and no path is a river, so no road is a river (I). II contradicts this, so it does not follow.", "सड़कें ⊂ रास्ते और कोई रास्ता नदी नहीं है, इसलिए कोई सड़क नदी नहीं है (I)। II इसका विरोधी है, इसलिए सही नहीं है।");
R("Missing Number", "medium", "Find the missing number: 3, 8, 15, 24, ?", "लुप्त संख्या ज्ञात कीजिए: 3, 8, 15, 24, ?", ["33", "35", "36", "38"], null, "B", "The terms are 2²−1, 3²−1, 4²−1, 5²−1; the next is 6²−1 = 35.", "पद 2²−1, 3²−1, 4²−1, 5²−1 हैं; अगला 6²−1 = 35 है।", () => [3, 8, 15, 24].every((v, i) => v === (i + 2) ** 2 - 1) && 6 ** 2 - 1 === 35);
R("Missing Number", "hard", "Find the missing number: 5, 10, 17, 26, 37, ?", "लुप्त संख्या ज्ञात कीजिए: 5, 10, 17, 26, 37, ?", ["46", "48", "50", "52"], null, "C", "The terms are 2²+1, 3²+1, 4²+1, 5²+1, 6²+1; the next is 7²+1 = 50.", "पद 2²+1, 3²+1, 4²+1, 5²+1, 6²+1 हैं; अगला 7²+1 = 50 है।", () => [5, 10, 17, 26, 37].every((v, i) => v === (i + 2) ** 2 + 1) && 7 ** 2 + 1 === 50);
R("Mathematical Operations", "medium", "If '+' means '×' and '×' means '+', what is the value of 6 + 4 × 2?", "यदि '+' का अर्थ '×' और '×' का अर्थ '+' है, तो 6 + 4 × 2 का मान क्या है?", ["14", "26", "32", "48"], null, "B", "Replace the signs: 6 × 4 + 2 = 24 + 2 = 26.", "चिह्न बदलने पर: 6 × 4 + 2 = 24 + 2 = 26।", () => 6 * 4 + 2 === 26);
R("Mathematical Operations", "medium", "If 'A' means '+' , 'B' means '−', 'C' means '×' and 'D' means '÷', what is the value of 8 C 3 A 12 D 4 B 5?", "यदि 'A' का अर्थ '+', 'B' का '−', 'C' का '×' और 'D' का '÷' है, तो 8 C 3 A 12 D 4 B 5 का मान क्या है?", ["20", "22", "24", "26"], null, "B", "The expression is 8 × 3 + 12 ÷ 4 − 5 = 24 + 3 − 5 = 27 − 5 = 22.", "व्यंजक 8 × 3 + 12 ÷ 4 − 5 = 24 + 3 − 5 = 22 है।", () => 8 * 3 + 12 / 4 - 5 === 22);
R("Seating Arrangement", "medium", "Four friends A, B, C and D sit in a row. A sits at the left end, D sits at the right end and B sits next to A. Who sits between B and D?", "चार मित्र A, B, C और D एक पंक्ति में बैठे हैं। A बाएँ छोर पर, D दाएँ छोर पर और B, A के बगल में बैठा है। B और D के बीच कौन बैठा है?", ["A", "C", "Nobody", "Cannot be determined"], ["A", "C", "कोई नहीं", "निर्धारित नहीं किया जा सकता"], "B", "The order is A, B, C, D, so C sits between B and D.", "क्रम A, B, C, D है, इसलिए B और D के बीच C बैठा है।");
R("Logical Order", "medium", "Arrange in a meaningful order: 1. Arrest 2. Crime 3. Trial 4. Investigation 5. Punishment", "अर्थपूर्ण क्रम में लगाइए: 1. गिरफ़्तारी 2. अपराध 3. मुक़दमा 4. जाँच 5. सज़ा", ["2, 4, 1, 3, 5", "2, 1, 4, 3, 5", "4, 2, 1, 3, 5", "2, 4, 3, 1, 5"], null, "A", "A crime (2) is investigated (4), the accused is arrested (1), tried (3) and then punished (5).", "अपराध (2) होता है, जाँच (4) होती है, आरोपी की गिरफ़्तारी (1), मुक़दमा (3) और फिर सज़ा (5) होती है।");

// ================================================================ MATHS (38)
M("Simplification", "easy", "What is the value of 125 − 45 ÷ 5 + 12 × 2?", "125 − 45 ÷ 5 + 12 × 2 का मान क्या है?", ["130", "136", "140", "146"], null, "C", "BODMAS: 45 ÷ 5 = 9 and 12 × 2 = 24, so 125 − 9 + 24 = 116 + 24 = 140.", "BODMAS: 45 ÷ 5 = 9 और 12 × 2 = 24, इसलिए 125 − 9 + 24 = 140।", () => 125 - 45 / 5 + 12 * 2 === 140);
M("Simplification", "medium", "What is the value of (8² − 6²) ÷ 14?", "(8² − 6²) ÷ 14 का मान क्या है?", ["1", "2", "3", "4"], null, "B", "8² − 6² = 64 − 36 = 28, and 28 ÷ 14 = 2.", "8² − 6² = 64 − 36 = 28, और 28 ÷ 14 = 2।", () => (64 - 36) / 14 === 2);
M("Percentage", "easy", "What is 45% of 560?", "560 का 45% कितना होता है?", ["238", "246", "252", "260"], null, "C", "45% of 560 = 560 × 45 / 100 = 252.", "560 का 45% = 560 × 45 / 100 = 252।", () => 560 * 45 / 100 === 252);
M("Percentage", "medium", "A student gets 36 marks out of 80. What is his percentage?", "एक विद्यार्थी को 80 में से 36 अंक मिलते हैं। उसका प्रतिशत क्या है?", ["40%", "42%", "45%", "48%"], null, "C", "Percentage = 36 / 80 × 100 = 45%.", "प्रतिशत = 36 / 80 × 100 = 45%।", () => 36 / 80 * 100 === 45);
M("Percentage", "medium", "The salary of a person is increased from ₹20,000 to ₹23,000. What is the percentage increase?", "एक व्यक्ति का वेतन ₹20,000 से बढ़कर ₹23,000 हो जाता है। प्रतिशत वृद्धि क्या है?", ["12%", "15%", "18%", "20%"], null, "B", "Increase = ₹3,000, so the percentage = 3000 / 20000 × 100 = 15%.", "वृद्धि = ₹3,000, इसलिए प्रतिशत = 3000 / 20000 × 100 = 15%।", () => 3000 / 20000 * 100 === 15);
M("Percentage", "medium", "In a village, 60% of the population is literate. If the village has 4,500 people, how many are illiterate?", "एक गाँव में 60% जनसंख्या साक्षर है। यदि गाँव की जनसंख्या 4,500 है, तो कितने निरक्षर हैं?", ["1,600", "1,700", "1,800", "1,900"], null, "C", "Illiterate = 40% of 4,500 = 1,800.", "निरक्षर = 4,500 का 40% = 1,800।", () => 4500 * 0.4 === 1800);
M("Profit & Loss", "easy", "A trader buys an article for ₹250 and sells it for ₹300. What is the profit percentage?", "एक व्यापारी ₹250 में वस्तु खरीदकर ₹300 में बेचता है। लाभ प्रतिशत क्या है?", ["15%", "18%", "20%", "25%"], null, "C", "Profit = ₹50, so profit % = 50 / 250 × 100 = 20%.", "लाभ = ₹50, इसलिए लाभ % = 50 / 250 × 100 = 20%।", () => 50 / 250 * 100 === 20);
M("Profit & Loss", "medium", "An article is sold at a loss of 10% for ₹630. What is its cost price?", "एक वस्तु 10% हानि पर ₹630 में बेची जाती है। उसका क्रय मूल्य क्या है?", ["₹650", "₹680", "₹700", "₹720"], ["₹650", "₹680", "₹700", "₹720"], "C", "CP = 630 / 0.9 = ₹700.", "क्रय मूल्य = 630 / 0.9 = ₹700।", () => 630 / 0.9 === 700);
M("Profit & Loss", "medium", "By selling an article for ₹1,080 a shopkeeper gains 20%. For what price should he sell it to gain 30%?", "एक वस्तु ₹1,080 में बेचने पर दुकानदार को 20% लाभ होता है। 30% लाभ के लिए उसे वह वस्तु कितने में बेचनी चाहिए?", ["₹1,150", "₹1,170", "₹1,200", "₹1,250"], ["₹1,150", "₹1,170", "₹1,200", "₹1,250"], "B", "CP = 1080 / 1.2 = ₹900. SP for a 30% gain = 900 × 1.3 = ₹1,170.", "क्रय मूल्य = 1080 / 1.2 = ₹900। 30% लाभ पर विक्रय मूल्य = 900 × 1.3 = ₹1,170।", () => 1080 / 1.2 * 1.3 === 1170);
M("Profit & Loss", "medium", "The cost price of 15 articles equals the selling price of 12 articles. What is the profit percentage?", "15 वस्तुओं का क्रय मूल्य 12 वस्तुओं के विक्रय मूल्य के बराबर है। लाभ प्रतिशत क्या है?", ["20%", "25%", "30%", "33.33%"], null, "B", "Let the cost of one article be ₹1, so SP of 12 = ₹15 and SP of 1 = ₹1.25. Profit = 25%.", "माना एक वस्तु का क्रय मूल्य ₹1 है, तो 12 का विक्रय मूल्य ₹15 और 1 का ₹1.25। लाभ = 25%।", () => (15 / 12 - 1) * 100 === 25);
M("Ratio & Proportion", "easy", "Divide ₹1,800 in the ratio 2 : 3 : 4. What is the largest share?", "₹1,800 को 2 : 3 : 4 के अनुपात में बाँटिए। सबसे बड़ा हिस्सा कितना है?", ["₹600", "₹700", "₹800", "₹900"], ["₹600", "₹700", "₹800", "₹900"], "C", "Total parts = 9, so one part = 200. The largest share = 4 × 200 = ₹800.", "कुल भाग = 9, इसलिए एक भाग = 200। सबसे बड़ा हिस्सा = 4 × 200 = ₹800।", () => 1800 / 9 * 4 === 800);
M("Ratio & Proportion", "medium", "If A : B = 2 : 3 and B : C = 4 : 5, what is A : B : C?", "यदि A : B = 2 : 3 और B : C = 4 : 5 है, तो A : B : C क्या है?", ["8 : 12 : 15", "2 : 3 : 5", "4 : 6 : 5", "8 : 10 : 15"], null, "A", "Make B equal: A : B = 8 : 12 and B : C = 12 : 15, so A : B : C = 8 : 12 : 15.", "B को समान बनाने पर A : B = 8 : 12 और B : C = 12 : 15, इसलिए A : B : C = 8 : 12 : 15।", () => 2 * 4 === 8 && 3 * 4 === 12 && 4 * 3 === 12 && 5 * 3 === 15);
M("Ratio & Proportion", "medium", "The ratio of the ages of a father and his son is 7 : 2. If the father is 42 years old, how old is the son?", "पिता और पुत्र की आयु का अनुपात 7 : 2 है। यदि पिता 42 वर्ष का है, तो पुत्र की आयु कितनी है?", ["10 years", "12 years", "14 years", "16 years"], ["10 वर्ष", "12 वर्ष", "14 वर्ष", "16 वर्ष"], "B", "One part = 42 / 7 = 6, so the son = 2 × 6 = 12 years.", "एक भाग = 42 / 7 = 6, इसलिए पुत्र = 2 × 6 = 12 वर्ष।", () => 42 / 7 * 2 === 12);
M("Average", "easy", "What is the average of 15, 25, 35, 45 and 55?", "15, 25, 35, 45 और 55 का औसत क्या है?", ["30", "35", "40", "45"], null, "B", "Sum = 175 and 175 / 5 = 35.", "योग = 175 और 175 / 5 = 35।", () => (15 + 25 + 35 + 45 + 55) / 5 === 35);
M("Average", "medium", "The average of 7 numbers is 20. If 6 is added to each number, what is the new average?", "7 संख्याओं का औसत 20 है। यदि प्रत्येक संख्या में 6 जोड़ दिया जाए, तो नया औसत क्या होगा?", ["23", "24", "26", "27"], null, "C", "Adding 6 to each number adds 6 to the average: 20 + 6 = 26.", "प्रत्येक संख्या में 6 जोड़ने पर औसत में भी 6 जुड़ता है: 20 + 6 = 26।", () => 20 + 6 === 26);
M("Average", "medium", "The average weight of 8 persons increases by 2 kg when a person weighing 60 kg is replaced by a new person. What is the weight of the new person?", "8 व्यक्तियों का औसत भार 2 किग्रा बढ़ जाता है जब 60 किग्रा वाले एक व्यक्ति की जगह नया व्यक्ति आता है। नए व्यक्ति का भार कितना है?", ["72 kg", "74 kg", "76 kg", "78 kg"], ["72 किग्रा", "74 किग्रा", "76 किग्रा", "78 किग्रा"], "C", "Total weight rises by 8 × 2 = 16 kg, so the new person weighs 60 + 16 = 76 kg.", "कुल भार 8 × 2 = 16 किग्रा बढ़ता है, इसलिए नए व्यक्ति का भार 60 + 16 = 76 किग्रा है।", () => 60 + 8 * 2 === 76);
M("Simple Interest", "easy", "What is the simple interest on ₹7,500 at 8% per annum for 3 years?", "₹7,500 पर 8% वार्षिक दर से 3 वर्ष का साधारण ब्याज कितना होगा?", ["₹1,600", "₹1,700", "₹1,800", "₹1,900"], ["₹1,600", "₹1,700", "₹1,800", "₹1,900"], "C", "SI = 7500 × 8 × 3 / 100 = ₹1,800.", "साधारण ब्याज = 7500 × 8 × 3 / 100 = ₹1,800।", () => 7500 * 8 * 3 / 100 === 1800);
M("Simple Interest", "medium", "At what rate per annum will ₹2,000 amount to ₹2,600 in 5 years at simple interest?", "साधारण ब्याज पर ₹2,000, 5 वर्ष में ₹2,600 हो जाने के लिए वार्षिक दर क्या होगी?", ["5%", "6%", "7%", "8%"], null, "B", "Interest = ₹600, so rate = 600 × 100 / (2000 × 5) = 6%.", "ब्याज = ₹600, इसलिए दर = 600 × 100 / (2000 × 5) = 6%।", () => 600 * 100 / (2000 * 5) === 6);
M("Compound Interest", "medium", "What is the compound interest on ₹5,000 at 20% per annum for 2 years, compounded annually?", "₹5,000 पर 20% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज (वार्षिक संयोजन) कितना होगा?", ["₹2,000", "₹2,100", "₹2,200", "₹2,400"], ["₹2,000", "₹2,100", "₹2,200", "₹2,400"], "C", "Amount = 5000 × 1.2 × 1.2 = ₹7,200. Compound interest = 7200 − 5000 = ₹2,200.", "मिश्रधन = 5000 × 1.2 × 1.2 = ₹7,200। चक्रवृद्धि ब्याज = 7200 − 5000 = ₹2,200।", () => Math.round(5000 * 1.2 * 1.2 - 5000) === 2200);
M("Time & Work", "easy", "A worker can complete a job in 30 days. What part of the job does he complete in 6 days?", "एक मज़दूर किसी काम को 30 दिन में पूरा कर सकता है। वह 6 दिन में काम का कितना भाग पूरा करेगा?", ["1/3", "1/4", "1/5", "1/6"], null, "C", "In one day he does 1/30 of the job, so in 6 days he does 6/30 = 1/5.", "एक दिन में वह 1/30 काम करता है, इसलिए 6 दिन में 6/30 = 1/5।", () => 6 / 30 === 1 / 5);
M("Time & Work", "medium", "A and B can do a work in 12 days and 4 days respectively. In how many days can they do it together?", "A और B किसी काम को क्रमशः 12 दिन और 4 दिन में कर सकते हैं। साथ मिलकर वे कितने दिन में करेंगे?", ["2 days", "3 days", "4 days", "5 days"], ["2 दिन", "3 दिन", "4 दिन", "5 दिन"], "B", "Per day: 1/12 + 1/4 = 4/12 = 1/3, so they take 3 days.", "प्रति दिन: 1/12 + 1/4 = 4/12 = 1/3, इसलिए 3 दिन लगेंगे।", () => Math.abs(1 / (1 / 12 + 1 / 4) - 3) < 1e-9);
M("Time & Work", "medium", "If 8 men can build a wall in 18 days, how many men are needed to build it in 12 days?", "यदि 8 आदमी एक दीवार 18 दिन में बना सकते हैं, तो उसे 12 दिन में बनाने के लिए कितने आदमी चाहिए?", ["10", "12", "14", "16"], null, "B", "Total work = 8 × 18 = 144 man-days. Men needed = 144 / 12 = 12.", "कुल कार्य = 8 × 18 = 144 आदमी-दिन। आवश्यक आदमी = 144 / 12 = 12।", () => 8 * 18 / 12 === 12);
M("Time & Distance", "easy", "A bus travels 240 km in 4 hours. What is its speed?", "एक बस 4 घंटे में 240 किमी चलती है। उसकी चाल क्या है?", ["50 km/h", "55 km/h", "60 km/h", "65 km/h"], ["50 किमी/घंटा", "55 किमी/घंटा", "60 किमी/घंटा", "65 किमी/घंटा"], "C", "Speed = 240 / 4 = 60 km/h.", "चाल = 240 / 4 = 60 किमी/घंटा।", () => 240 / 4 === 60);
M("Time & Distance", "medium", "A man walks at 5 km/h. How long will he take to cover 12.5 km?", "एक आदमी 5 किमी/घंटा की चाल से चलता है। 12.5 किमी तय करने में उसे कितना समय लगेगा?", ["2 hours", "2.5 hours", "3 hours", "3.5 hours"], ["2 घंटे", "2.5 घंटे", "3 घंटे", "3.5 घंटे"], "B", "Time = 12.5 / 5 = 2.5 hours.", "समय = 12.5 / 5 = 2.5 घंटे।", () => 12.5 / 5 === 2.5);
M("Time & Distance", "medium", "Two trains of length 100 m and 120 m run in opposite directions at 40 km/h and 50 km/h. How long do they take to cross each other?", "100 मी और 120 मी लंबी दो रेलगाड़ियाँ विपरीत दिशाओं में 40 किमी/घंटा और 50 किमी/घंटा की चाल से चलती हैं। वे एक-दूसरे को कितने समय में पार करेंगी?", ["8.8 s", "9.6 s", "10.4 s", "12 s"], ["8.8 से", "9.6 से", "10.4 से", "12 से"], "A", "Relative speed = 90 km/h = 25 m/s. Distance = 220 m. Time = 220 / 25 = 8.8 seconds.", "सापेक्ष चाल = 90 किमी/घंटा = 25 मी/से। दूरी = 220 मी। समय = 220 / 25 = 8.8 सेकंड।", () => 220 / (90 * 5 / 18) === 8.8);
M("Mensuration", "easy", "What is the perimeter of a rectangle 18 m long and 12 m wide?", "18 मी लंबे और 12 मी चौड़े आयत का परिमाप कितना है?", ["48 m", "54 m", "60 m", "72 m"], ["48 मी", "54 मी", "60 मी", "72 मी"], "C", "Perimeter = 2 × (18 + 12) = 60 m.", "परिमाप = 2 × (18 + 12) = 60 मी।", () => 2 * (18 + 12) === 60);
M("Mensuration", "easy", "What is the area of a triangle with base 20 cm and height 15 cm?", "20 सेमी आधार और 15 सेमी ऊँचाई वाले त्रिभुज का क्षेत्रफल कितना है?", ["100 cm²", "150 cm²", "200 cm²", "300 cm²"], ["100 सेमी²", "150 सेमी²", "200 सेमी²", "300 सेमी²"], "B", "Area = ½ × 20 × 15 = 150 cm².", "क्षेत्रफल = ½ × 20 × 15 = 150 सेमी²।", () => 0.5 * 20 * 15 === 150);
M("Mensuration", "medium", "What is the volume of a cuboid of length 10 cm, breadth 8 cm and height 5 cm?", "10 सेमी लंबाई, 8 सेमी चौड़ाई और 5 सेमी ऊँचाई वाले घनाभ का आयतन कितना है?", ["300 cm³", "350 cm³", "400 cm³", "450 cm³"], ["300 सेमी³", "350 सेमी³", "400 सेमी³", "450 सेमी³"], "C", "Volume = 10 × 8 × 5 = 400 cm³.", "आयतन = 10 × 8 × 5 = 400 सेमी³।", () => 10 * 8 * 5 === 400);
M("Mensuration", "medium", "The radius of a circle is 21 cm. What is its circumference? (π = 22/7)", "एक वृत्त की त्रिज्या 21 सेमी है। उसकी परिधि कितनी है? (π = 22/7)", ["66 cm", "112 cm", "132 cm", "154 cm"], ["66 सेमी", "112 सेमी", "132 सेमी", "154 सेमी"], "C", "Circumference = 2πr = 2 × 22/7 × 21 = 132 cm.", "परिधि = 2πr = 2 × 22/7 × 21 = 132 सेमी।", () => 2 * (22 / 7) * 21 === 132);
M("HCF & LCM", "easy", "What is the HCF of 54 and 90?", "54 और 90 का HCF क्या है?", ["9", "12", "18", "27"], null, "C", "54 = 2 × 3³ and 90 = 2 × 3² × 5, so HCF = 2 × 3² = 18.", "54 = 2 × 3³ और 90 = 2 × 3² × 5, इसलिए HCF = 2 × 3² = 18।", () => gcd(54, 90) === 18);
M("HCF & LCM", "medium", "What is the smallest number that is exactly divisible by 6, 9 and 15?", "वह सबसे छोटी संख्या क्या है जो 6, 9 और 15 से पूर्णतः विभाज्य हो?", ["30", "45", "90", "180"], null, "C", "LCM of 6, 9 and 15 = 2 × 3² × 5 = 90.", "6, 9 और 15 का LCM = 2 × 3² × 5 = 90।", () => { const l = (a, b) => a / gcd(a, b) * b; return l(l(6, 9), 15) === 90; });
M("HCF & LCM", "medium", "Three bells ring every 10, 15 and 20 minutes. If they ring together at 8:00 a.m., when will they next ring together?", "तीन घंटियाँ क्रमशः हर 10, 15 और 20 मिनट पर बजती हैं। यदि वे सुबह 8:00 बजे एक साथ बजती हैं, तो अगली बार एक साथ कब बजेंगी?", ["8:30 a.m.", "8:45 a.m.", "9:00 a.m.", "9:15 a.m."], ["सुबह 8:30", "सुबह 8:45", "सुबह 9:00", "सुबह 9:15"], "C", "LCM of 10, 15 and 20 = 60 minutes, so they ring together again at 9:00 a.m.", "10, 15 और 20 का LCM = 60 मिनट, इसलिए वे फिर से सुबह 9:00 बजे एक साथ बजेंगी।", () => { const l = (a, b) => a / gcd(a, b) * b; return l(l(10, 15), 20) === 60; });
M("Algebra", "easy", "If 4x + 9 = 33, what is the value of x?", "यदि 4x + 9 = 33 है, तो x का मान क्या है?", ["4", "5", "6", "7"], null, "C", "4x = 33 − 9 = 24, so x = 6.", "4x = 33 − 9 = 24, इसलिए x = 6।", () => (33 - 9) / 4 === 6);
M("Algebra", "medium", "If a − b = 3 and ab = 10, what is the value of a² + b²?", "यदि a − b = 3 और ab = 10 है, तो a² + b² का मान क्या है?", ["19", "23", "29", "31"], null, "C", "a² + b² = (a − b)² + 2ab = 9 + 20 = 29.", "a² + b² = (a − b)² + 2ab = 9 + 20 = 29।", () => 9 + 20 === 29);
M("Number System", "easy", "What is the sum of the first 10 natural numbers?", "पहली 10 प्राकृत संख्याओं का योग क्या है?", ["45", "50", "55", "65"], null, "C", "Sum = 10 × 11 / 2 = 55.", "योग = 10 × 11 / 2 = 55।", () => 10 * 11 / 2 === 55);
M("Number System", "medium", "What is the remainder when 1,234 is divided by 9?", "1,234 को 9 से भाग देने पर शेषफल क्या होगा?", ["0", "1", "2", "3"], null, "B", "The digit sum 1 + 2 + 3 + 4 = 10 and 10 leaves remainder 1 when divided by 9.", "अंकों का योग 1 + 2 + 3 + 4 = 10 है और 10 को 9 से भाग देने पर शेष 1 बचता है।", () => 1234 % 9 === 1);
M("Number System", "medium", "Which of the following numbers is divisible by 11?", "निम्नलिखित में से कौन-सी संख्या 11 से विभाज्य है?", ["2,345", "3,731", "4,862", "5,001"], null, "C", "4,862: (4 + 6) − (8 + 2) = 0, so it is divisible by 11 (4862 = 11 × 442).", "4,862: (4 + 6) − (8 + 2) = 0, इसलिए यह 11 से विभाज्य है (4862 = 11 × 442)।", () => [2345, 3731, 4862, 5001].filter((n) => n % 11 === 0).join() === "4862");
M("Ages", "medium", "The sum of the present ages of a mother and her daughter is 50 years. After 5 years the mother will be three times as old as the daughter. What is the daughter's present age?", "माँ और उसकी पुत्री की वर्तमान आयु का योग 50 वर्ष है। 5 वर्ष बाद माँ की आयु पुत्री की आयु की तीन गुनी हो जाएगी। पुत्री की वर्तमान आयु क्या है?", ["10 years", "12 years", "15 years", "20 years"], ["10 वर्ष", "12 वर्ष", "15 वर्ष", "20 वर्ष"], "A", "After 5 years the sum is 60, in the ratio 3 : 1, so the daughter will be 15 and is now 10 years old.", "5 वर्ष बाद योग 60 होगा, अनुपात 3 : 1, इसलिए पुत्री 15 वर्ष की होगी और अभी 10 वर्ष की है।", () => (50 + 10) / 4 - 5 === 10);

